<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\MagicLink\Application\Usecase\RequestMagicLink;

use DateTimeImmutable;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\MagicLink;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkMailGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkEnabledGateway;

class RequestMagicLinkUsecase
{
    public function __construct(
        private readonly UserReadGateway $users,
        private readonly TenantReadGateway $tenants,
        private readonly ClientStoreGateway $clients,
        private readonly MagicLinkGateway $gateway,
        private readonly MagicLinkMailGateway $mailer,
        private readonly MagicLinkEnabledGateway $enabled,
        private readonly string $baseUrl,
    ) {
    }

    public function isEnabled(string $tenantName): bool
    {
        return $this->enabled->isEnabled($tenantName);
    }

    public function request(
        string $email,
        string $clientId,
        string $redirectUri,
        string $tenantName,
        string $scope = 'openid email',
        ?string $state = null,
        string $nonce = '',
    ): void {
        if (!$this->enabled->isEnabled($tenantName)) {
            return;
        }

        $tenant = $this->tenants->findOneByName($tenantName);
        if ($tenant === null || !$tenant->isEnabled()) {
            return;
        }

        $user = $this->users->findOneByTenantAndName($tenant, $email);
        if ($user === null || !$user->isEnabled()) {
            return;
        }

        $tenantUid = $tenant->uid();
        $userUid = $user->uid();
        if ($tenantUid === null || $userUid === null) {
            return;
        }

        $client = $this->clients->publicClientData($clientId, $tenantName, $redirectUri, $scope);
        if ($client === null) {
            return;
        }

        $rawToken = bin2hex(random_bytes(32));
        $tokenHash = hash('sha256', $rawToken);
        $expiresAt = new DateTimeImmutable('+15 minutes');

        $magicLink = MagicLink::create(
            uid: Random::comb(),
            tenantId: $tenantName,
            userUid: $userUid,
            clientId: $clientId,
            tokenHash: $tokenHash,
            redirectUri: $redirectUri,
            scope: $scope,
            state: $state,
            expiresAt: $expiresAt,
            nonce: $nonce,
        );

        $this->gateway->store($magicLink);

        $verifyUrl = rtrim($this->baseUrl, '/') . '/oauth/openid/' . urlencode($tenantName)
            . '/magic-link/verify?token=' . urlencode($rawToken) . '&client_id=' . urlencode($clientId);

        $this->mailer->sendMagicLink(
            toEmail: $email,
            userName: $user->getName(),
            tenant: new TenantRef($tenantUid),
            magicUrl: $verifyUrl,
            expiresAt: $expiresAt,
        );
    }
}
